  opacity: 0;
  width: 0;
  height: 0;
}

.choice-box {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  border: 1.5px solid var(--color-border);
  border-radius: 6px;
  background: var(--color-surface);
  display: grid;
  place-items: center;
  transition: border-color .15s, background .15s;
