/* ── Result banner ────────────────────────────────────── */
.result-banner {
  display: none;
  margin-top: 28px;
  padding: 18px 22px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  align-items: flex-start;
  gap: 12px;
