  transform: translateY(1px);
  box-shadow: none;
}

.btn-submit svg {
  transition: transform .15s;
}

.btn-submit:hover svg {
  transform: translateX(3px);
}

/* ── Result banner ────────────────────────────────────── */
.result-banner {
  display: none;
  margin-top: 28px;
  padding: 18px 22px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
  align-items: flex-start;
  gap: 12px;
}

.result-banner.show {
  display: flex;
}

.result-banner.success {
  background: #ecfdf5;
  border: 1.5px solid #6ee7b7;
  color: #065f46;
}

.result-banner.partial {
  background: #fffbeb;
  border: 1.5px solid #fcd34d;
  color: #92400e;
}

.result-banner.empty {
  background: #fef2f2;
  border: 1.5px solid #fca5a5;
  color: #991b1b;
}

.result-banner svg {
  flex-shrink: 0;
  margin-top: 1px;
}

.result-banner strong {
  display: block;
  font-weight: 700;
  margin-bottom: 2px;
}

/* ── Responsive ───────────────────────────────────────── */
@media (max-width: 480px) {
  .quiz-card {
    padding: 24px 20px;
  }

  .choices {
    grid-template-columns: 1fr;
  }

  .quiz-footer {
    flex-direction: column-reverse;
    align-items: stretch;
  }

  .btn-submit {
    justify-content: center;
  }
}

const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1 of 3",
    text: "Which of the following are statically typed languages?",
    help: "In a statically typed language, variable types are known at compile time rather than at runtime.",
    choices: [
      { id: "q1a", label: "TypeScript" },
      { id: "q1b", label: "Python" },
      { id: "q1c", label: "Rust" },
      { id: "q1d", label: "Java" },
    ],
    correct: ["q1a", "q1c", "q1d"],
  },
  {
    id: "q2",
    number: "Question 2 of 3",
    text: "Which languages are primarily used for systems programming?",
    choices: [
      { id: "q2a", label: "C" },
      { id: "q2b", label: "Ruby" },
      { id: "q2c", label: "C++" },
      { id: "q2d", label: "Rust" },
    ],
    correct: ["q2a", "q2c", "q2d"],
  },
  {
    id: "q3",
    number: "Question 3 of 3",
    text: "Which of the following languages support first-class functions?",
    choices: [
      { id: "q3a", label: "JavaScript" },
      { id: "q3b", label: "Haskell" },
      { id: "q3c", label: "Python" },
      { id: "q3d", label: "SQL" },
    ],
    correct: ["q3a", "q3b", "q3c"],
  },
];

function CheckIcon() {
  return `<svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true">
    <path d="M2 6l3 3 5-5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

function InfoIcon() {
  return `<svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
    <path d="M8 7v4M8 5v.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
  </svg>`;
}

function ArrowIcon() {
  return `<svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <path d="M3 8h10M9 4l4 4-4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

function renderChoice(choice, questionId) {
  return `
    <label class="choice-label" for="${choice.id}">
      <input type="checkbox" id="${choice.id}" name="${questionId}" value="${choice.id}">
      <span class="choice-box">${CheckIcon()}</span>
      <span class="choice-text">${choice.label}</span>
    </label>`;
}

function renderQuestion(q) {
  const helpHtml = q.help
    ? `<p class="form-field__help">${InfoIcon()}<span>${q.help}</span></p>`
    : "";

  return `
    <div class="form-field" id="${q.id}-field">
      <p class="form-field__number">${q.number}</p>
      <p class="form-field__label">${q.text}</p>
      ${helpHtml}
      <div class="choices" role="group" aria-label="${q.text}">
        ${q.choices.map((c) => renderChoice(c, q.id)).join("")}
      </div>
    </div>`;
}

function renderApp() {
  const app = document.getElementById("app");
  app.innerHTML = `
    <div class="quiz-wrapper">
      <header class="quiz-header">
        <span class="eyebrow">Knowledge Check</span>
        <h1>Computer Languages Quiz</h1>
        <p>Select all answers that apply for each question.</p>
      </header>

      <div class="quiz-card">
        <div class="progress-bar-wrap" aria-label="Quiz progress">
          <div class="progress-bar-labels">
            <span>Progress</span>
            <span id="progress-label">0 / 3 answered</span>
          </div>
          <div class="progress-bar-track">
            <div class="progress-bar-fill" id="progress-fill"></div>
          </div>
        </div>

        <form id="quiz-form" novalidate>
          ${QUESTIONS.map(renderQuestion).join("")}

          <footer class="quiz-footer">
            <span class="hint">Select all that apply</span>
            <button type="submit" class="btn-submit">
              Submit Quiz ${ArrowIcon()}
            </button>
          </footer>
        </form>

        <div class="result-banner" id="result-banner" role="alert" aria-live="polite"></div>
      </div>
    </div>`;

  document.getElementById("quiz-form").addEventListener("change", updateProgress);
  document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
}

function getAnsweredCount() {
  return QUESTIONS.filter((q) =>
    document.querySelectorAll(`input[name="${q.id}"]:checked`).length > 0
  ).length;
}

function updateProgress() {
  const answered = getAnsweredCount();
  const total = QUESTIONS.length;
  const pct = Math.round((answered / total) * 100);
  document.getElementById("progress-fill").style.width = pct + "%";
  document.getElementById("progress-label").textContent = `${answered} / ${total} answered`;
}

function arraysEqual(a, b) {
  return a.length === b.length && [...a].sort().every((v, i) => v === [...b].sort()[i]);
}

function handleSubmit(e) {
  e.preventDefault();
  const banner = document.getElementById("result-banner");

  const answeredCount = getAnsweredCount();
  if (answeredCount === 0) {
    showBanner(banner, "empty", "No answers selected", "Please answer at least one question before submitting.");
    return;
  }

  let correct = 0;
  QUESTIONS.forEach((q) => {
    const selected = [...document.querySelectorAll(`input[name="${q.id}"]:checked`)].map((el) => el.value);
    if (arraysEqual(selected, q.correct)) correct++;
  });

  if (correct === QUESTIONS.length) {
    showBanner(banner, "success", "Perfect score! 🎉", `You got all ${QUESTIONS.length} questions correct. Excellent work!`);
  } else if (correct > 0) {
    showBanner(banner, "partial", `${correct} of ${QUESTIONS.length} correct`, "Good effort! Review the questions and try again to improve your score.");
  } else {
    showBanner(banner, "empty", "No correct answers", "None of your answers were fully correct. Try reviewing the topics and give it another shot!");
  }

  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function showBanner(banner, type, title, message) {
  const icons = {
    success: `<svg width="20" height="20" viewBox="0 0 20 20" fill="none"><circle cx="10" cy="10" r="9" stroke="#10b981" stroke-width="1.5"/><path d="M6 10l3 3 5-5" stroke="#10b981" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
    partial: `<svg width="20" height="20" viewBox="0 0 20 20" fill="none"><circle cx="10" cy="10" r="9" stroke="#f59e0b" stroke-width="1.5"/><path d="M10 6v5M10 13v1" stroke="#f59e0b" stroke-width="1.8" stroke-linecap="round"/></svg>`,
    empty: `<svg width="20" height="20" viewBox="0 0 20 20" fill="none"><circle cx="10" cy="10" r="9" stroke="#ef4444" stroke-width="1.5"/><path d="M7 7l6 6M13 7l-6 6" stroke="#ef4444" stroke-width="1.8" stroke-linecap="round"/></svg>`,
  };
  banner.className = `result-banner show ${type}`;
  banner.innerHTML = `${icons[type]}<div><strong>${title}</strong>${message}</div>`;
}

renderApp();

