+  width: 20px;
+  height: 20px;
+  flex-shrink: 0;
+  border: 1.5px solid var(--color-border);
+  border-radius: 6px;
+  background: var(--color-surface);
+  display: grid;
+  place-items: center;
+  transition: border-color .15s, background .15s;
+}
+
+.choice-box svg {
+  opacity: 0;
+  transform: scale(.6);
+  transition: opacity .15s, transform .15s;
+  color: #fff;
+}
+
+.choice-label input:checked ~ .choice-box {
+  background: var(--color-check-bg);
+  border-color: var(--color-check-bg);
+}
+
+.choice-label input:checked ~ .choice-box svg {
+  opacity: 1;
+  transform: scale(1);
+}
+
+.choice-label:has(input:checked) {
+  border-color: var(--color-primary);
+  background: var(--color-primary-light);
+  box-shadow: 0 0 0 3px rgba(91,110,245,.12);
+}
+
+.choice-label:focus-within {
+  outline: 2px solid var(--color-primary);
+  outline-offset: 2px;
+}
+
+/* ── Footer / submit ──────────────────────────────────── */
+.quiz-footer {
+  margin-top: 32px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 16px;
+}
+
+.quiz-footer .hint {
+  font-size: 13px;
+  color: var(--color-text-muted);
+}
+
+.btn-submit {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 13px 28px;
+  background: var(--color-primary);
+  color: #fff;
+  font-family: var(--font);
+  font-size: 15px;
+  font-weight: 600;
+  border: none;
+  border-radius: var(--radius-md);
+  cursor: pointer;
+  box-shadow: var(--shadow-btn);
+  transition: background .15s, transform .1s, box-shadow .15s;
+}
+
+.btn-submit:hover {
+  background: var(--color-primary-hover);
+  box-shadow: 0 4px 14px rgba(91,110,245,.45);
+}
+
+.btn-submit:active {
+  transform: translateY(1px);
+  box-shadow: none;
+}
+
+.btn-submit svg {
+  transition: transform .15s;
+}
+
+.btn-submit:hover svg {
+  transform: translateX(3px);
+}
+
+/* ── Result banner ────────────────────────────────────── */
+.result-banner {
+  display: none;
+  margin-top: 28px;
+  padding: 18px 22px;
+  border-radius: var(--radius-md);
+  font-size: 14px;
+  font-weight: 500;
+  line-height: 1.5;
+  align-items: flex-start;
+  gap: 12px;
+}
+
+.result-banner.show {
+  display: flex;
+}
+
+.result-banner.success {
+  background: #ecfdf5;
+  border: 1.5px solid #6ee7b7;
+  color: #065f46;
+}
+
+.result-banner.partial {
+  background: #fffbeb;
+  border: 1.5px solid #fcd34d;
+  color: #92400e;
+}
+
+.result-banner.empty {
+  background: #fef2f2;
+  border: 1.5px solid #fca5a5;
+  color: #991b1b;
+}
+
+.result-banner svg {
+  flex-shrink: 0;
+  margin-top: 1px;
+}
+
+.result-banner strong {
+  display: block;
+  font-weight: 700;
+  margin-bottom: 2px;
+}
+
+/* ── Responsive ───────────────────────────────────────── */
+@media (max-width: 480px) {
+  .quiz-card {
+    padding: 24px 20px;
+  }
+
+  .choices {
+    grid-template-columns: 1fr;
+  }
+
+  .quiz-footer {
+    flex-direction: column-reverse;
+    align-items: stretch;
+  }
+
+  .btn-submit {
+    justify-content: center;
+  }
+}
+
')
